type Session = { user: User | null; wallet: Wallet | null; loading: boolean; refresh: () => Promise<void>; logout: () => Promise<void> }
const SessionContext = createContext<Session>(null!)
const useSession = () => useContext(SessionContext)
function useResource<T>(loader: () => Promise<T>, fallback: T) {
  const [value, setValue] = useState<T>(fallback); const [loading, setLoading] = useState(true); const [error, setError] = useState("")
  const refresh = useCallback(async () => { setLoading(true); try { setValue(await loader()); setError("") } catch (e) { setError((e as Error).message) } finally { setLoading(false) } }, [loader])
  useEffect(() => { refresh() }, [refresh]); return { value, loading, error, refresh }
}
function Avatar({ src, name, size = "md", className = "" }: { src?: string; name?: string; size?: "xs" | "sm" | "md" | "lg" | "xl"; className?: string }) {
  const px = size === "xl" ? 94 : size === "lg" ? 66 : size === "sm" ? 44 : size === "xs" ? 32 : 54
  return <AntAvatar className={"avatar avatar-" + size + " " + className} size={px} src={src || undefined} style={!src ? { background: "linear-gradient(140deg,#ffb8cd,#bca5ff)", color: "#17285f" } : undefined}>{!src && (name || "星").slice(0, 1)}</AntAvatar>
}
function Empty({ children }: { children: ReactNode }) { return <div className="empty-state">{children}</div> }
function ErrorBanner({ text }: { text: string }) { return text ? <div className="error-banner">{text}</div> : null }

function Shell({ children }: { children: ReactNode }) {
  const location = useLocation(); const navigate = useNavigate(); const [drawer, setDrawer] = useState(false); const [query, setQuery] = useState("")
  const immersive = /^\/conversations\/[^/]+/.test(location.pathname)
  const [user, setUser] = useState<User | null>(null); const [wallet, setWallet] = useState<Wallet | null>(null); const [loading, setLoading] = useState(Boolean(localStorage.getItem("user_token")))
  const refresh = useCallback(async () => { if (!localStorage.getItem("user_token")) { setUser(null); setWallet(null); setLoading(false); return } try { const [u, w] = await Promise.all([api<User>("/me"), getWallet()]); setUser(u); setWallet(w) } catch { localStorage.removeItem("user_token"); setUser(null); setWallet(null) } finally { setLoading(false) } }, [])
  useEffect(() => { refresh(); const expired = () => { setUser(null); setWallet(null) }; window.addEventListener("user-session-expired", expired); return () => window.removeEventListener("user-session-expired", expired) }, [refresh])
  const logout = async () => { try { await api("/auth/logout", {}) } catch { /* local logout still succeeds */ } finally { localStorage.removeItem("user_token"); setUser(null); setWallet(null); navigate("/login") } }
  const active = (path: string) => location.pathname === path || (path !== "/" && location.pathname.startsWith(path)); const selected = navItems.find(x => active(x.path))?.path || "/characters"
  return <SessionContext.Provider value={{ user, wallet, loading, refresh, logout }}><Layout className={"app-shell " + (immersive ? "is-immersive" : "")}>
    <Layout.Sider className={"desktop-sidebar " + (drawer ? "drawer-open" : "")} width={207} theme="light"><Link to="/characters" className="brand"><span className="brand-mark">★</span><span>星语AI</span></Link><Menu mode="inline" selectedKeys={[selected]} items={navItems.map(({ path, label, icon: Icon }) => ({ key: path, icon: <Icon size={22} strokeWidth={1.9} />, label: <Link to={path} onClick={() => setDrawer(false)}>{label}</Link> }))} /><div className="sidebar-promo"><div className="promo-star">★<Sparkles size={18} /></div><b>与 AI 伙伴<br />一起探索更多可能</b><Link to="/discover">探索更多可能 <ArrowRight size={15} /></Link></div><Link to={user ? "/me" : "/login"} className="sidebar-account"><Avatar name={user?.name || "星"} size="sm" /><span><b>{user?.name || "星空旅人"}</b><small>{wallet?.membership || "登录后开启故事"}</small></span><ChevronDown size={16} /></Link></Layout.Sider>
    {drawer && <button className="drawer-scrim" onClick={() => setDrawer(false)} aria-label="关闭菜单" />}<Layout className="main-layout"><Layout.Header className="topbar"><button className="mobile-menu" onClick={() => setDrawer(true)} aria-label="打开菜单"><MenuIcon /></button><Link to="/characters" className="mobile-brand"><span className="brand-mark">★</span><span>星语AI</span></Link><form className="searchbar" onSubmit={e => { e.preventDefault(); navigate("/characters?q=" + encodeURIComponent(query)) }}><Search size={20} /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="搜索角色、对话或功能..." aria-label="搜索角色、对话或功能" /></form><div className="top-actions"><Link to="/me/transactions" className="notice"><Badge count={3} size="small"><Bell size={22} /></Badge></Link><Link to="/me/wallet" className="balance"><Coins size={18} fill="currentColor" /> <b>{wallet?.balance?.toLocaleString() || 1280}</b></Link><Link to="/me/membership" className="membership"><Sparkles size={15} /> 开通会员</Link><Link to={user ? "/me" : "/login"}><Avatar name={user?.name || "星"} size="sm" /></Link></div></Layout.Header><Layout.Content className="content-area">{children}</Layout.Content></Layout>
    <nav className="mobile-nav">{navItems.map(({ path, label, icon: Icon }) => <Link to={path} className={active(path) ? "active" : ""} key={path}><Icon size={22} /><span>{label}</span></Link>)}</nav>
  </Layout></SessionContext.Provider>
}
function RequireAuth({ children }: { children: ReactNode }) { const { user, loading } = useSession(); const location = useLocation(); if (loading) return <Empty>正在加载你的空间…</Empty>; return user ? <>{children}</> : <Navigate to={"/login?next=" + encodeURIComponent(location.pathname)} replace /> }

