function ChatPage() {
  const { id = "" } = useParams(); const navigate = useNavigate(); const data = useResource(() => getMessages(id), demoMessages); const [input, setInput] = useState(""); const [sending, setSending] = useState(false); const [showOverlay, setShowOverlay] = useState(false); const [messages, setMessages] = useState<ChatMessage[]>(demoMessages); const current = demoConversations.find(x => x.id === id) || demoConversations[0]
  useEffect(() => { if (data.value.length) setMessages(data.value) }, [data.value])
  const send = async (text: string) => { if (!text.trim() || sending) return; const value = text.trim(); setInput(""); setMessages(prev => [...prev, { id: "local-" + Date.now(), role: "user", content: value, createdAt: "刚刚", credits: 1 }]); setSending(true); try { let answer = ""; const reply = await streamMessage(id, value, crypto.randomUUID(), new AbortController().signal, delta => { answer += delta; setMessages(prev => [...prev.filter(m => m.id !== "streaming"), { id: "streaming", role: "assistant", content: answer, createdAt: "刚刚", credits: 1 }]) }); setMessages(prev => [...prev.filter(m => m.id !== "streaming"), { id: reply.messageId, role: "assistant", content: reply.reply, createdAt: "刚刚", credits: reply.chargedCredits }]) } catch { setMessages(prev => [...prev, { id: "error-" + Date.now(), role: "assistant", content: "暂时没有收到回复，请稍后再试。", createdAt: "", credits: 0 }]) } finally { setSending(false) } }
  const bubbleItems = messages.map(msg => ({ key: msg.id, role: msg.role === "assistant" ? "ai" : "user", content: <div className={"chat-rich " + (msg.role === "assistant" ? "assistant-rich" : "user-rich")}>{msg.content.split("\\n").map((line, i) => line.trim() ? <p key={i} className={line.startsWith("“") ? "quote" : ""}>{line}</p> : <span key={i} className="line-break" />)}</div>, avatar: msg.role === "assistant" ? <Avatar src={current.image} name={current.title} size="sm" /> : <Avatar name="我" size="sm" />, placement: msg.role === "assistant" ? "start" : "end" as const, footer: <time>{msg.createdAt}</time> }))
  return <div className="chat-page"><header className="chat-top"><button onClick={() => navigate("/conversations")} aria-label="返回"><ArrowLeft size={29} /></button><div><h1>{current.title}<span>AI</span></h1><p>Flux-0217 · 16K <ChevronDown size={16} /></p></div><button onClick={() => setShowOverlay(true)} aria-label="更多"><MoreHorizontal size={29} /></button></header><div className="chat-workspace"><div className="chat-header-card"><Avatar src={current.image} name={current.title} size="md" /><div><b>{current.title}<span>AI</span></b><small>温柔治愈 · 学霸学姐 · 永远支持你</small></div><div className="chat-tools\"><button onClick={() => setShowOverlay(true)}><Heart /><small>状态栏</small></button><button><UsersRound /><small>人物关系</small></button><button><Star /><small>收藏</small></button><button><Share2 /><small>分享</small></button><button><Settings /><small>设置</small></button></div></div><div className="chat-stream"><Bubble.List items={bubbleItems as any} className="chat-bubbles" /></div><div className="chat-options"><button>我想了解这本书</button><button>去海边书店</button><button>继续聊聊</button><button><RefreshCw size={18} /> 换一批</button></div><div className="chat-composer\"><button className="code-button">&#123;&#125;</button><Sender value={input} onChange={setInput} onSubmit={send} loading={sending} placeholder="请输入消息..." prefix={<button aria-label="语音"><Mic size={23} /></button>} suffix={<button aria-label="添加"><Plus size={27} /></button>} /></div></div>{showOverlay && <div className="relationship-overlay" onClick={() => setShowOverlay(false)}><div className="relationship-card" onClick={e => e.stopPropagation()}><button className="overlay-close" onClick={() => setShowOverlay(false)}><X /></button><Avatar src={current.image} name={current.title} size="lg" /><h2>你与 {current.title} 的关系</h2><strong>88%</strong><div className="relationship-progress"><i /></div><p>亲密无间 · 形影不离</p><div className="relationship-stats\"><span>好感度 <b>88</b></span><span>信任度 <b>76</b></span><span>默契值 <b>92</b></span></div></div></div>}</div>
}
function DiscoverMiniCard({ character, compact = false }: { character: Character; compact?: boolean }) { return <Link to={"/characters/" + character.id} className={compact ? "discover-mini-card compact" : "discover-mini-card"}><div className="discover-mini-cover" style={{ backgroundImage: "url(" + (character.image || fallbackArt) + ")" }}><span><Heart size={13} fill="currentColor" /> {character.cost > 10 ? "1.2万" : "9,421"}</span></div><div className="discover-mini-body"><b>{character.name.split(" · ")[0]}</b><div>{character.tags.slice(0, 3).map(x => <Tag key={x}>{x}</Tag>)}</div><p>{character.subtitle}</p></div></Link> }
function DiscoverPage() { const cards = demoCharacters.slice(0, 5); return <div className="discover-page"><div className="discover-tabs"><Link to="/discover" className="active">猜你喜欢</Link><Link to="/discover/category">新手</Link><Link to="/discover/search">最新</Link><Link to="/discover/rankings">榜单</Link><Link to="/discover/category">分类</Link><Link to="/studio/draw">绘图</Link></div><div className="discover-feature-cards"><Link to="/studio/draw" className="discover-feature-card drawing"><div><b>绘图</b><p>用文字描绘想象<br />生成精美的画作</p><span>开始创作 <ArrowRight size={14} /></span></div><WandSparkles size={66} /></Link><Link to="/me/tasks" className="discover-feature-card tasks"><div><b>任务</b><p>完成趣味任务<br />解锁更多精彩内容</p><span>去看看 <ArrowRight size={14} /></span></div><Check size={61} /></Link><Link to="/studio" className="discover-feature-card studio"><div><b>创作中心</b><p>创建属于你的角色<br />分享你的故事</p><span>开始创作 <ArrowRight size={14} /></span></div><Pencil size={61} /></Link><Link to="/studio/worldbook" className="discover-feature-card world"><div><b>世界书</b><p>补充角色的背景设定<br />让对话更加丰富</p><span>去看看 <ArrowRight size={14} /></span></div><BookOpenIcon /></Link></div><section className="discover-section"><div className="section-title"><div><span>★</span><h2>精选角色</h2></div><Link to="/characters">查看更多 <ArrowRight size={16} /></Link></div><div className="discover-mini-grid">{cards.map(x => <DiscoverMiniCard character={x} key={x.id} />)}</div></section><section className="discover-section newcomer-section"><div className="section-title"><div><span>●</span><h2>新手推荐</h2></div><Link to="/characters">查看更多 <ArrowRight size={16} /></Link></div><div className="discover-mini-grid compact-grid">{cards.map(x => <DiscoverMiniCard character={x} compact key={"compact-" + x.id} />)}</div></section></div> }
function DiscoverSubPage({ kind }: { kind: "category" | "search" | "rankings" }) { const [query, setQuery] = useState(kind === "search" ? "海边" : ""); const title = kind === "category" ? "分类专题" : kind === "rankings" ? "人气榜单" : "搜索结果"; const list = demoCharacters.filter(x => !query || (x.name + " " + x.subtitle + " " + x.tags.join(" ")).includes(query)); return <div className="sub-page"><Link to="/discover" className="back-link"><ArrowLeft size={18} /> 返回发现</Link><div className="page-head"><div><h1>{title}</h1><p>{kind === "category" ? "按主题和氛围找到适合你的角色。" : kind === "rankings" ? "本周最受欢迎的角色。" : "从角色名称、标签和介绍中查找。"}</p></div>{kind === "search" && <Input prefix={<Search size={18} />} value={query} onChange={e => setQuery(e.target.value)} />}</div>{kind === "category" && <div className="category-tags">{["全部", "校园", "奇幻", "治愈", "冒险", "职场", "旅行"].map(x => <Tag key={x}>{x}</Tag>)}</div>}{kind === "rankings" && <Segmented options={["今日", "本周", "本月"]} defaultValue="本周" />}{kind === "search" && <p className="result-count">找到 {list.length} 个角色</p>}<div className="rank-list">{list.map((x, i) => <div className="rank-row" key={x.id}><strong>{kind === "rankings" ? i + 1 : ""}</strong><Avatar src={x.image} name={x.name} size="md" /><span><b>{x.name}</b><small>{x.subtitle}</small><em>{x.tags.join(" · ")}</em></span><Link to={"/characters/" + x.id}>查看 <ChevronRight size={16} /></Link></div>)}</div></div> }

function StudioHubPage() { return <div className="studio-page"><div className="page-head"><div><h1>创作中心</h1><p>把灵感变成可对话的角色。</p></div></div><div className="studio-hero"><div><span>开始你的创作</span><h2>创建一个属于你的角色</h2><p>从角色身份、开场对话到世界书，一步步完成你的作品。</p><div className="studio-actions"><Button type="primary" href="/studio/create" icon={<Plus size={17} />}>创建角色</Button><Button href="/studio/import" icon={<Upload size={17} />}>导入角色卡</Button></div></div><div className="studio-visual"><Sparkles size={58} /><div /><div /><div /></div></div><div className="studio-tools"><Link to="/studio/create"><Pencil /><b>简易创建角色</b><small>快速开始</small></Link><Link to="/studio/identity"><UsersRound /><b>角色核心身份</b><small>设定性格与背景</small></Link><Link to="/studio/openings"><MessageCircle /><b>开场对话</b><small>写下第一句话</small></Link><Link to="/studio/worldbook"><BookOpenIcon /><b>世界书</b><small>补充世界设定</small></Link><Link to="/studio/voices"><Mic /><b>角色声优</b><small>选择声音</small></Link><Link to="/studio/presets"><Settings /><b>预设管理</b><small>管理回复风格</small></Link><Link to="/studio/draw"><ImagePlus /><b>绘图生成</b><small>为灵感配图</small></Link><Link to="/studio/import"><FileJson /><b>角色卡导入</b><small>支持 JSON</small></Link></div></div> }
function BookOpenIcon() { return <span className="simple-icon">▤</span> }
function StudioCreatePage() { const [status, setStatus] = useState(""); const [busy, setBusy] = useState(false); const save = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const values = Object.fromEntries(new FormData(e.currentTarget)); setBusy(true); try { await createCreatorCharacter({ name: String(values.name), subtitle: String(values.subtitle), description: String(values.description), opening: String(values.opening), tags: String(values.tags || "").split(",").map(x => x.trim()).filter(Boolean), gender: String(values.gender), image: fallbackArt, online: true, cost: 1, published: false }); setStatus("角色草稿已保存") } catch (e) { setStatus((e as Error).message) } finally { setBusy(false) } }; return <div className="editor-page"><Link to="/studio" className="back-link"><ArrowLeft size={18} /> 返回创作中心</Link><div className="editor-head"><div><h1>简易创建角色</h1><p>先完成角色的核心信息，之后可以继续补充细节。</p></div><span>1 / 4</span></div><div className="editor-layout"><nav className="editor-steps\"><b className="active">01 <span>基础信息</span></b><b>02 <span>身份设定</span></b><b>03 <span>开场对话</span></b><b>04 <span>预览发布</span></b></nav><form className="editor-form" onSubmit={save}><label>角色名称<input name="name" required placeholder="例如：夏棠 · 温柔学姐" /></label><label>一句话介绍<input name="subtitle" required placeholder="让人一眼记住她" /></label><label>角色简介<textarea name="description" rows={6} required placeholder="性格、背景、关系与相处方式" /></label><label>开场白<textarea name="opening" rows={4} placeholder="欢迎用户进入故事" /></label><label>标签<input name="tags" placeholder="治愈,校园,温柔" /></label><div className="editor-footer"><Button href="/studio">取消</Button><Button type="primary" htmlType="submit" loading={busy}>保存并继续 <ArrowRight size={16} /></Button></div>{status && <p className="form-status">{status}</p>}</form></div></div> }
function StudioToolPage({ title, description, kind }: { title: string; description: string; kind: string }) { const [saved, setSaved] = useState(false); return <div className="editor-page"><Link to="/studio" className="back-link"><ArrowLeft size={18} /> 返回创作中心</Link><div className="page-head"><div><h1>{title}</h1><p>{description}</p></div><Tag color="purple">创作工具</Tag></div><section className="tool-editor"><div className="tool-editor-top"><div className="tool-icon"><WandSparkles size={22} /></div><div><h2>{kind}</h2><p>保存后可以随时回来继续编辑。</p></div></div><label>名称<input placeholder={"输入" + title + "名称"} /></label><label>内容<textarea rows={11} placeholder="写下你的设定、指令或说明" /></label><div className="editor-footer"><span className="form-status">{saved ? "草稿已保存" : ""}</span><Button type="primary" onClick={() => setSaved(true)} icon={<Check size={16} />}>保存草稿</Button></div></section></div> }
function ImportPage() { const [status, setStatus] = useState(""); const [busy, setBusy] = useState(false); const upload = async (e: ChangeEvent<HTMLInputElement>) => { const file = e.target.files?.[0]; if (!file) return; setBusy(true); try { const raw = JSON.parse(await file.text()); const card = raw.data || raw; await createCreatorCharacter({ name: card.name || "导入角色", subtitle: card.description?.slice(0, 60) || "导入的角色卡", description: card.description || "", opening: card.first_mes || "", tags: card.tags || [], gender: card.gender || "other", image: fallbackArt, online: true, cost: 1, published: false }); setStatus("角色卡已导入为草稿") } catch (e) { setStatus("导入失败：" + (e as Error).message) } finally { setBusy(false) } }; return <div className="editor-page"><Link to="/studio" className="back-link"><ArrowLeft size={18} /> 返回创作中心</Link><div className="page-head"><div><h1>角色卡导入</h1><p>支持 JSON / Chara Card v2，导入后会保存为私有草稿。</p></div></div><section className="import-box"><FileJson size={56} /><h2>选择角色卡文件</h2><p>导入的内容会自动填入角色编辑器，你可以继续修改。</p><label className="gradient-upload"><Upload size={17} /> {busy ? "导入中…" : "选择 JSON 文件"}<input type="file" accept="application/json,.json" onChange={upload} /></label>{status && <p className="form-status">{status}</p>}</section></div> }

function ProfilePage() { const { user, wallet, logout } = useSession(); return <div className="profile-page"><section className="profile-banner"><Avatar name={user?.name || "星"} size="xl" /><div><span>我的空间</span><h1>{user?.name || "星空旅人"}</h1><p>与 AI 一起，探索无限可能</p><Tag color="purple"><Star size={13} /> {wallet?.membership || "免费用户"}</Tag></div><Link to="/me/edit"><Pencil size={17} /> 编辑资料</Link></section><div className="profile-stats"><div><span>积分余额</span><b>{wallet?.balance?.toLocaleString() || "1280"}</b><Link to="/me/wallet">充值 <ChevronRight size={15} /></Link></div><div><span>我的角色</span><b>6</b><Link to="/me/roles">管理角色 <ChevronRight size={15} /></Link></div><div><span>收藏角色</span><b>12</b><Link to="/me/favorites">查看收藏 <ChevronRight size={15} /></Link></div></div><div className="profile-menu"><Link to="/me/roles"><Pencil /><span><b>我的角色</b><small>管理草稿与已发布作品</small></span><ChevronRight /></Link><Link to="/me/favorites"><Heart /><span><b>收藏</b><small>保存你想再次见面的角色</small></span><ChevronRight /></Link><Link to="/gallery"><ImageIcon /><span><b>我的图片</b><small>生成历史与灵感收藏</small></span><ChevronRight /></Link><Link to="/me/credits"><WalletCards /><span><b>积分与订单</b><small>充值、会员和消费记录</small></span><ChevronRight /></Link><Link to="/me/tasks"><Check /><span><b>任务签到</b><small>完成任务领取奖励</small></span><ChevronRight /></Link><Link to="/me/settings"><Settings /><span><b>设置</b><small>账号与偏好设置</small></span><ChevronRight /></Link></div><button className="logout-button" onClick={logout}><LogOut size={16} /> 退出登录</button></div> }
function ProfileEditPage() { const { user } = useSession(); const [name, setName] = useState(user?.name || "星空旅人"); return <div className="editor-page"><Link to="/me" className="back-link"><ArrowLeft size={18} /> 返回我的</Link><div className="page-head"><div><h1>资料编辑</h1><p>修改你的公开昵称与个人介绍。</p></div></div><section className="profile-edit-card"><Avatar name={name} size="xl" /><label>昵称<input value={name} onChange={e => setName(e.target.value)} /></label><label>个人介绍<textarea rows={5} defaultValue="热爱阅读与旅行，喜欢和 AI 聊聊生活。" /></label><div className="editor-footer"><Button href="/me">取消</Button><Button type="primary" onClick={() => message.success("资料已保存")}>保存更改</Button></div></section></div> }
function FavoritesPage() { const data = useResource(() => api<Character[]>("/favorites"), []); return <div className="sub-page"><div className="page-head"><div><h1>收藏</h1><p>保存你想再次见面的角色。</p></div><Input prefix={<Search size={18} />} placeholder="搜索收藏" /></div><div className="favorite-switch\"><button className="active">角色</button><button>图片</button></div>{data.value.length ? <div className="role-grid">{data.value.map((x, i) => <RoleCard key={x.id} character={{ ...x, image: x.image || coverArt[i % coverArt.length] }} />)}</div> : <Empty>还没有收藏角色，去角色库看看吧。</Empty>}</div> }
function MyRolesPage() { const data = useResource(() => api<Character[]>("/creator/characters"), []); return <div className="sub-page"><div className="page-head"><div><h1>我的角色</h1><p>管理你创建的角色草稿与已发布作品。</p></div><Button type="primary" href="/studio/create" icon={<Plus size={17} />}>创建角色</Button></div>{data.value.length ? <div className="created-grid">{data.value.map(x => <Link key={x.id} to={"/characters/" + x.id} className="created-card"><img src={x.image || fallbackArt} alt="" /><div><b>{x.name}</b><Tag>{x.published ? "已发布" : "草稿"}</Tag><small>{x.subtitle}</small></div></Link>)}</div> : <Empty>还没有角色草稿，去创作中心开始吧。</Empty>}</div> }
function WalletPage({ membership = false }: { membership?: boolean }) { const plans = useResource(() => api<Plan[]>("/plans"), []); const [orders, setOrders] = useState<Order[]>([]); const [status, setStatus] = useState(""); const buy = async (id: string) => { try { const order = await createOrder(id); setOrders(x => [order, ...x]); setStatus(order.paymentUrl ? "订单已创建，点击支付链接完成支付。" : "订单已创建。") } catch (e) { setStatus((e as Error).message) } }; const shown = plans.value.filter(x => x.type === (membership ? "membership" : "recharge")); return <div className="sub-page wallet-page"><Link to="/me" className="back-link"><ArrowLeft size={18} /> 返回我的</Link><div className="page-head"><div><h1>{membership ? "会员充值" : "积分与订单"}</h1><p>{membership ? "解锁更多模型、声音与创作额度。" : "充值积分，继续和喜欢的角色聊天。"}</p></div></div><div className="plan-grid">{(shown.length ? shown : [{ id: "demo-plan-1", name: membership ? "星语会员 · 月卡" : "1280 积分", price: membership ? 19.9 : 12.8, credits: 1280, type: membership ? "membership" : "recharge" } as Plan]).map(p => <div className={"plan-card " + (membership ? "premium" : "")} key={p.id}><Sparkles size={24} /><h2>{p.name}</h2><strong>¥{p.price}</strong><p>{p.credits || 0} 积分 · {membership ? "会员专属权益" : "即时到账"}</p><Button type="primary" onClick={() => buy(p.id)}>立即购买</Button></div>)}</div>{status && <p className="form-status">{status}</p>}{orders.length > 0 && <div className="order-list">{orders.map(x => <div key={x.id}><span>{x.plan}</span><small>{x.orderNo}</small><b>¥{x.amount}</b><Tag>{x.status}</Tag></div>)}</div>}</div> }
function TasksPage() { const tasks = useResource(getTasks, []); const [checked, setChecked] = useState(false); const [status, setStatus] = useState(""); const doCheckin = async () => { try { await checkin(); setChecked(true); setStatus("签到成功，积分已到账") } catch (e) { setStatus((e as Error).message) } }; const claim = async (id: string) => { try { await claimTask(id); tasks.refresh(); setStatus("奖励已领取") } catch (e) { setStatus((e as Error).message) } }; return <div className="sub-page tasks-page"><div className="page-head"><div><h1>任务签到</h1><p>完成一点小目标，积累更多对话额度。</p></div></div><section className="checkin-panel"><div><span>连续签到</span><h2>本周已签到 {checked ? 3 : 2} 天</h2><div className="week-strip">{["一", "二", "三", "四", "五", "六", "日"].map((x, i) => <span className={i < (checked ? 3 : 2) ? "checked" : ""} key={x}><b>{i + 1}</b><small>周{x}</small></span>)}</div></div><Button type="primary" disabled={checked} onClick={doCheckin}>{checked ? "今日已签到" : "签到"}</Button></section><section className="tasks-panel"><div className="section-title"><div><span>今日任务</span><h2>完成任务领取奖励</h2></div><ListFilter size={20} /></div>{tasks.value.map(task => <div className="task-row" key={task.id}><span className="task-check"><Check size={16} /></span><span><b>{task.name}</b><small>{task.description}</small><i><em style={{ width: Math.min(100, task.progress / Math.max(1, task.target) * 100) + "%" }} /></i></span><Button size="small" disabled={task.claimed} onClick={() => claim(task.id)}>{task.claimed ? "已领取" : task.progress >= task.target ? "领取 " + task.reward : "去完成"}</Button></div>)}{status && <p className="form-status">{status}</p>}</section></div> }
function GalleryPage() { const data = useResource(getImages, []); const [preview, setPreview] = useState<Image | null>(null); const upload = async (e: ChangeEvent<HTMLInputElement>) => { const file = e.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = async () => { try { await uploadImage({ name: file.name, base64: String(reader.result).split(",")[1] }); data.refresh() } catch { /* empty */ } }; reader.readAsDataURL(file) }; return <div className="sub-page gallery-page"><div className="page-head"><div><h1>我的图片</h1><p>生成历史保留在这里，收藏你想留下的瞬间。</p></div><div><label className="outline-upload"><Upload size={16} /> 上传图片<input type="file" accept="image/png,image/jpeg,image/webp" onChange={upload} /></label><Button type="primary" href="/studio/draw" icon={<ImagePlus size={16} />}>绘图创作</Button></div></div>{data.value.length ? <div className="gallery-grid">{data.value.map(image => <div className="gallery-card" key={image.id}><button onClick={() => setPreview(image)}><img src={image.url} alt={image.prompt} /></button><div><span>{image.prompt || "未命名图片"}</span><button onClick={() => updateImage(image.id, !image.favorite).then(data.refresh)} aria-label="收藏"><Heart size={16} fill={image.favorite ? "currentColor" : "none"} /></button><button onClick={() => deleteImage(image.id).then(data.refresh)} aria-label="删除"><Trash2 size={16} /></button></div></div>)}</div> : <Empty>暂无图片，在创作中心生成一张吧。</Empty>}{preview && <div className="image-modal" onClick={() => setPreview(null)}><img src={preview.url} alt={preview.prompt} /><button onClick={() => setPreview(null)}><X /></button></div>}</div> }
function DrawPage() { const [prompt, setPrompt] = useState("海边晚霞与一本书"); const [busy, setBusy] = useState(false); return <div className="editor-page"><Link to="/studio" className="back-link"><ArrowLeft size={18} /> 返回创作中心</Link><div className="page-head"><div><h1>绘图生成</h1><p>把一句话变成一张可以保存的灵感图。</p></div><Segmented options={["创作", "编辑", "我的作品"]} defaultValue="创作" /></div><div className="draw-layout"><section className="draw-form"><label>模型<select defaultValue="Anime"><option>Anime</option><option>Flux</option></select></label><label>提示词<textarea rows={8} value={prompt} onChange={e => setPrompt(e.target.value)} /></label><div className="draw-chips"><Tag>风景</Tag><Tag>晚霞</Tag><Tag>书店</Tag><Tag>治愈</Tag></div><div className="draw-ratios"><span>画幅</span><button>1:1</button><button>2:3</button><button className="active">3:2</button></div><Button type="primary" size="large" loading={busy} onClick={() => { setBusy(true); setTimeout(() => setBusy(false), 700) }} icon={<WandSparkles size={17} />}>生成图片</Button></section><section className="draw-preview"><ImagePlus size={56} /><h2>你的下一张图</h2><p>生成完成后会显示在这里。</p></section></div></div> }
function LoginPage() { const { user, refresh } = useSession(); const navigate = useNavigate(); const [search] = useSearchParams(); const [register, setRegister] = useState(false); const [error, setError] = useState(""); const next = search.get("next") || "/characters"; if (user) return <Navigate to={next} replace />; return <div className="auth-page"><div className="auth-art"><div><span className="brand-mark">★</span><h1>星语AI</h1><p>和喜欢的角色，<br />聊聊每一个心事。</p></div></div><div className="auth-card"><Link to="/characters" className="auth-brand"><span className="brand-mark">★</span><span>星语AI</span></Link><span className="auth-eyebrow">你的故事，从这里开始</span><h1>{register ? "创建账号" : "欢迎回来"}</h1><p>登录后收藏角色、同步对话和管理你的创作。</p><form onSubmit={async e => { e.preventDefault(); const values = Object.fromEntries(new FormData(e.currentTarget)); try { if (register) await api("/auth/register", values); const result = await api<{ token: string }>("/auth/login", { email: values.email, password: values.password }); localStorage.setItem("user_token", result.token); await refresh(); navigate(next) } catch (e) { setError((e as Error).message) } }}><label>邮箱<input name="email" type="email" required /></label>{register && <label>昵称<input name="name" required /></label>}<label>密码<input name="password" type="password" minLength={10} required /></label>{error && <ErrorBanner text={error} />}<Button type="primary" htmlType="submit" block>{register ? "注册并登录" : "登录"}</Button></form><button className="switch-auth" onClick={() => { setRegister(x => !x); setError("") }}>{register ? "已有账号，去登录" : "没有账号，去注册"}</button></div></div> }
function NewConversationPage() { const [query, setQuery] = useState(""); const list = demoCharacters.filter(x => (x.name + x.subtitle).includes(query)); const navigate = useNavigate(); return <div className="sub-page"><Link to="/conversations" className="back-link"><ArrowLeft size={18} /> 返回对话</Link><div className="page-head"><div><h1>新建对话</h1><p>选择一个角色，开始你们的第一句话。</p></div><Input prefix={<Search size={18} />} value={query} onChange={e => setQuery(e.target.value)} placeholder="搜索角色" /></div><div className="role-grid">{list.map(x => <button className="new-chat-card" key={x.id} onClick={async () => { try { const c = await createConversation(x.id); navigate("/conversations/" + c.id) } catch { navigate("/conversations") } }}><img src={x.image} alt="" /><span><b>{x.name}</b><small>{x.subtitle}</small></span><ArrowRight size={17} /></button>)}</div></div> }
function BranchesPage() { return <div className="sub-page"><Link to="/conversations" className="back-link"><ArrowLeft size={18} /> 返回对话</Link><div className="page-head"><div><h1>历史与分支</h1><p>从不同的节点继续故事，保留每一次选择。</p></div></div><section className="branch-board"><div className="branch-node active"><span>当前故事</span><b>海边书店的下午</b><small>15:18 · 3 条消息</small></div><ArrowDownIcon /><div className="branch-node"><span>分支 01</span><b>一起去海边书店</b><small>未继续 · 昨天</small></div><div className="branch-node"><span>分支 02</span><b>聊聊书里的主人公</b><small>未继续 · 昨天</small></div></section></div> }
function ArrowDownIcon() { return <span className="arrow-down">↓</span> }
function ConversationSettingsPage() { return <div className="sub-page settings-page"><Link to="/conversations" className="back-link"><ArrowLeft size={18} /> 返回对话</Link><div className="page-head"><div><h1>对话设置</h1><p>独立配置模型、语音、预设和聊天背景。</p></div></div><section className="settings-list"><label>模型<select defaultValue="Flux-0217"><option>Flux-0217 · 16K</option><option>Nova-3 · 32K</option></select></label><label>回复预设<select defaultValue="温柔陪伴"><option>温柔陪伴</option><option>故事叙述</option><option>简洁对话</option></select></label><label>聊天背景<select defaultValue="浅蓝渐变"><option>浅蓝渐变</option><option>纯白</option><option>夜间蓝</option></select></label><div className="editor-footer"><Button href="/conversations">取消</Button><Button type="primary" onClick={() => message.success("设置已保存")}>保存设置</Button></div></section></div> }
function SettingsPage() { return <div className="sub-page settings-page"><Link to="/me" className="back-link"><ArrowLeft size={18} /> 返回我的</Link><div className="page-head"><div><h1>设置</h1><p>管理账号、通知和界面偏好。</p></div></div><section className="settings-list"><label>界面主题<select defaultValue="星语浅色"><option>星语浅色</option><option>跟随系统</option></select></label><label>消息通知<select defaultValue="开启"><option>开启</option><option>关闭</option></select></label><label>默认语言<select defaultValue="简体中文"><option>简体中文</option><option>English</option></select></label><div className="editor-footer"><Button type="primary" onClick={() => message.success("设置已保存")}>保存设置</Button></div></section></div> }
function TransactionsPage() { return <div className="sub-page"><Link to="/me" className="back-link"><ArrowLeft size={18} /> 返回我的</Link><div className="page-head"><div><h1>消费记录</h1><p>查看充值与对话消费明细。</p></div></div><div className="order-list"><div><span>对话消耗</span><small>2026-10-06 15:18</small><b>-1 积分</b><Tag>已完成</Tag></div><div><span>积分充值</span><small>2026-10-01 09:42</small><b>+1280 积分</b><Tag color="green">已到账</Tag></div></div></div> }

function App() { return <ConfigProvider theme={{ token: { colorPrimary: "#a94cf0", colorInfo: "#6a87ef", colorText: "#0d2162", colorTextSecondary: "#6f82b2", colorBgLayout: "#eef7ff", colorBorder: "#dfe8fa", borderRadius: 14, fontFamily: "\"PingFang SC\", \"Noto Sans SC\", system-ui, sans-serif" }, components: { Button: { controlHeight: 42, borderRadius: 13, fontWeight: 600 }, Input: { controlHeight: 44, activeBorderColor: "#a94cf0", hoverBorderColor: "#c493f5" } } }}><AntApp><Shell><Routes><Route path="/" element={<Navigate to="/characters" replace />} /><Route path="/characters" element={<RolesPage />} /><Route path="/characters/:id" element={<CharacterDetailPage />} /><Route path="/conversations" element={<RequireAuth><ConversationsPage /></RequireAuth>} /><Route path="/conversations/new" element={<RequireAuth><NewConversationPage /></RequireAuth>} /><Route path="/conversations/branches" element={<RequireAuth><BranchesPage /></RequireAuth>} /><Route path="/conversations/:id/settings" element={<RequireAuth><ConversationSettingsPage /></RequireAuth>} /><Route path="/conversations/:id" element={<RequireAuth><ChatPage /></RequireAuth>} /><Route path="/discover" element={<DiscoverPage />} /><Route path="/discover/category" element={<DiscoverSubPage kind="category" />} /><Route path="/discover/search" element={<DiscoverSubPage kind="search" />} /><Route path="/discover/rankings" element={<DiscoverSubPage kind="rankings" />} /><Route path="/studio" element={<RequireAuth><StudioHubPage /></RequireAuth>} /><Route path="/studio/create" element={<RequireAuth><StudioCreatePage /></RequireAuth>} /><Route path="/studio/identity" element={<RequireAuth><StudioToolPage title="角色核心身份" description="定义角色的性格、背景与关系。" kind="身份设定" /></RequireAuth>} /><Route path="/studio/openings" element={<RequireAuth><StudioToolPage title="开场对话" description="写下角色与用户见面的第一句话。" kind="开场白" /></RequireAuth>} /><Route path="/studio/worldbook" element={<RequireAuth><StudioToolPage title="世界书" description="补充角色所在世界的地点、人物与规则。" kind="世界书条目" /></RequireAuth>} /><Route path="/studio/voices" element={<RequireAuth><StudioToolPage title="角色声优" description="为角色选择适合的声音。" kind="声音设置" /></RequireAuth>} /><Route path="/studio/presets" element={<RequireAuth><StudioToolPage title="预设管理" description="管理不同的回复风格与模型配置。" kind="预设" /></RequireAuth>} /><Route path="/studio/import" element={<RequireAuth><ImportPage /></RequireAuth>} /><Route path="/studio/publish" element={<RequireAuth><StudioToolPage title="预览发布" description="确认角色资料、开场白和可见范围后再公开。" kind="发布前检查" /></RequireAuth>} /><Route path="/studio/panels" element={<RequireAuth><StudioToolPage title="互动面板" description="为角色配置关系值、状态和快捷选项。" kind="面板配置" /></RequireAuth>} /><Route path="/studio/summon" element={<RequireAuth><StudioToolPage title="AI 定制角色" description="用一句话描述想要的角色，再继续完善细节。" kind="AI 定制" /></RequireAuth>} /><Route path="/studio/voice-create" element={<RequireAuth><StudioToolPage title="新建声优" description="创建一个属于角色的专属声线。" kind="新建声优" /></RequireAuth>} /><Route path="/studio/draw" element={<RequireAuth><DrawPage /></RequireAuth>} /><Route path="/studio/edit" element={<RequireAuth><DrawPage /></RequireAuth>} /><Route path="/me" element={<RequireAuth><ProfilePage /></RequireAuth>} /><Route path="/me/edit" element={<RequireAuth><ProfileEditPage /></RequireAuth>} /><Route path="/me/roles" element={<RequireAuth><MyRolesPage /></RequireAuth>} /><Route path="/me/favorites" element={<RequireAuth><FavoritesPage /></RequireAuth>} /><Route path="/me/wallet" element={<RequireAuth><WalletPage /></RequireAuth>} /><Route path="/me/credits" element={<RequireAuth><WalletPage /></RequireAuth>} /><Route path="/me/membership" element={<RequireAuth><WalletPage membership /></RequireAuth>} /><Route path="/me/transactions" element={<RequireAuth><TransactionsPage /></RequireAuth>} /><Route path="/me/tasks" element={<RequireAuth><TasksPage /></RequireAuth>} /><Route path="/me/settings" element={<RequireAuth><SettingsPage /></RequireAuth>} /><Route path="/gallery" element={<RequireAuth><GalleryPage /></RequireAuth>} /><Route path="/login" element={<LoginPage />} /><Route path="*" element={<Navigate to="/characters" replace />} /></Routes></Shell></AntApp></ConfigProvider> }
export default App





